function testRoute() {
  console.log(route("GET", "/shifts"))
  console.log(route("POST", "/shifts/6/signups"))
  console.log(route("DELETE", "/signups/13"))
  console.log(route("GET", "/members"))
}

function route(method, pathname) {
  const parts = pathname.split("/").filter(part => part !== "")
  if (method === "GET" && parts.length === 1 && parts[0] === "shifts") {
    return "list"
  }
  if (method === "GET" && parts.length === 2 && parts[0] === "shifts") {
    return "one"
  }
  if (method === "POST" && parts.length === 3 && parts[0] === "shifts" && parts[2] === "signups") {
    return "signup"
  }
  if (method === "DELETE" && parts.length === 2 && parts[0] === "signups") {
    return "cancel"
  }
  return "none"
}
